<?php
require __DIR__.'/base.php';$id=autenticado();exigir_post();$sol=(int)($_POST['id_solicitacao']??0);$texto=trim($_POST['conteudo']??'');if(!$sol||!$texto||mb_strlen($texto)>300)responder('nok','Mensagem deve conter de 1 a 300 caracteres.');
$db=banco();$db->begin_transaction();try{$stmt=$db->prepare('SELECT s.id_usuario_solicitante,i.id_usuario_publicador FROM solicitacao s JOIN solicitacao_item si ON si.id_solicitacao=s.id_solicitacao JOIN item i ON i.id_item=si.id_item WHERE s.id_solicitacao=?');$stmt->bind_param('i',$sol);$stmt->execute();$r=$stmt->get_result()->fetch_assoc();$stmt->close();if(!$r||!in_array($id,[(int)$r['id_usuario_solicitante'],(int)$r['id_usuario_publicador']],true))throw new Exception('Conversa não autorizada.');$dest=$id===(int)$r['id_usuario_solicitante']?(int)$r['id_usuario_publicador']:(int)$r['id_usuario_solicitante'];$lido=0;$stmt=$db->prepare('INSERT INTO mensagem(conteudo,data_hora,lida,id_usuario,id_solicitacao) VALUES (?,NOW(),?,?,?)');$stmt->bind_param('siii',$texto,$lido,$id,$sol);$stmt->execute();$stmt->close();$tipo='Mensagem';$prev='Nova mensagem: '.mb_substr($texto,0,120);$stmt=$db->prepare('INSERT INTO notificacao(status_leitura,tipo_notificacao,conteudo_notificacao,data_notificacao,id_usuario_notificado,data_hora) VALUES (?,?,?,CURDATE(),?,NOW())');$stmt->bind_param('issi',$lido,$tipo,$prev,$dest);$stmt->execute();$stmt->close();$db->commit();responder('ok','Mensagem enviada.');}catch(Throwable $e){$db->rollback();responder('nok','Não foi possível enviar. Tente novamente.');}
